//! The Rust port of src/ring.cpp (CodeCoreMorph, D-56): textkit's ring buffer and
//! checksum, behind the C API of include/textkit/ring.h.

use std::os::raw::c_int;

/// A fixed-capacity ring buffer; C code sees it only through a pointer. It keeps the C
/// API's name, so the generated header matches include/textkit/ring.h.
#[allow(non_camel_case_types)]
pub struct tk_ring {
    slots: Vec<i32>,
    head: usize,
    count: usize,
}

/// A new, empty ring that holds up to `capacity` values; NULL when capacity is 0.
#[no_mangle]
pub extern "C" fn tk_ring_new(capacity: usize) -> *mut tk_ring {
    if capacity == 0 {
        return std::ptr::null_mut();
    }
    Box::into_raw(Box::new(tk_ring { slots: vec![0; capacity], head: 0, count: 0 }))
}

/// Frees a ring; NULL is allowed.
///
/// # Safety
/// `ring` is NULL or a pointer from `tk_ring_new` that hasn't been freed.
#[no_mangle]
pub unsafe extern "C" fn tk_ring_free(ring: *mut tk_ring) {
    if !ring.is_null() {
        drop(Box::from_raw(ring));
    }
}

/// Appends a value: 1 if it was stored, 0 if the ring is full.
///
/// # Safety
/// `ring` is a live pointer from `tk_ring_new`.
#[no_mangle]
pub unsafe extern "C" fn tk_ring_push(ring: *mut tk_ring, value: i32) -> c_int {
    let ring = &mut *ring;
    if ring.count == ring.slots.len() {
        return 0;
    }
    let tail = (ring.head + ring.count) % ring.slots.len();
    ring.slots[tail] = value;
    ring.count += 1;
    1
}

/// Takes the oldest value into `*out`: 1 if there was one, 0 if the ring is empty.
///
/// # Safety
/// `ring` is a live pointer from `tk_ring_new`; `out` points to writable memory.
#[no_mangle]
pub unsafe extern "C" fn tk_ring_pop(ring: *mut tk_ring, out: *mut i32) -> c_int {
    let ring = &mut *ring;
    if ring.count == 0 {
        return 0;
    }
    *out = ring.slots[ring.head];
    ring.head = (ring.head + 1) % ring.slots.len();
    ring.count -= 1;
    1
}

/// # Safety
/// `ring` is a live pointer from `tk_ring_new`.
#[no_mangle]
pub unsafe extern "C" fn tk_ring_len(ring: *const tk_ring) -> usize {
    (*ring).count
}

/// # Safety
/// `ring` is a live pointer from `tk_ring_new`.
#[no_mangle]
pub unsafe extern "C" fn tk_ring_capacity(ring: *const tk_ring) -> usize {
    (*ring).slots.len()
}

/// The sum of the values in the ring.
///
/// # Safety
/// `ring` is a live pointer from `tk_ring_new`.
#[no_mangle]
pub unsafe extern "C" fn tk_ring_sum(ring: *const tk_ring) -> i64 {
    let ring = &*ring;
    (0..ring.count).map(|i| i64::from(ring.slots[(ring.head + i) % ring.slots.len()])).sum()
}

/// The Adler-32 checksum of `len` bytes.
///
/// # Safety
/// `data` points to `len` readable bytes, or `len` is 0.
#[no_mangle]
pub unsafe extern "C" fn tk_checksum(data: *const u8, len: usize) -> u32 {
    const MOD: u32 = 65521;
    let bytes = if len == 0 { &[][..] } else { std::slice::from_raw_parts(data, len) };
    let (mut a, mut b) = (1u32, 0u32);
    for &byte in bytes {
        a = (a + u32::from(byte)) % MOD;
        b = (b + a) % MOD;
    }
    (b << 16) | a
}
